/* Surprise cards. ids link to people (p:) and events (e:). */
facts: [
  {h:"Cleopatra lived closer to the Moon landing than to the Great Pyramid", t:"The Great Pyramid was about 2,500 years old when Cleopatra was born. The Moon landing came about 2,000 years after her death.", links:["p:cleopatra","e:great-pyramid","e:moon-landing"]},
  {h:"Nintendo is older than Van Gogh's death", t:"Nintendo was founded in Kyoto in September 1889, the same year the Eiffel Tower opened. Van Gogh died in July 1890.", links:["e:nintendo-founded","p:van-gogh","e:eiffel-tower"]},
  {h:"Oxford is older than the Aztec capital", t:"Teaching at Oxford was going on by 1096. The Aztecs founded Tenochtitlan in 1325, more than 200 years later.", links:["e:oxford-teaching","e:tenochtitlan"]},
  {h:"Lincoln and Darwin were born on the same day", t:"Both were born on February 12, 1809, one in a Kentucky log cabin, the other in a large house in Shrewsbury, England.", links:["p:lincoln","p:darwin"]},
  {h:"The class of 1809", t:"Lincoln, Darwin, Poe and Mendelssohn were all born in 1809.", links:["p:lincoln","p:darwin","p:poe","p:mendelssohn"]},
  {h:"1616 lost three giants", t:"Shakespeare, Cervantes and Tokugawa Ieyasu, the founder of Japan's last shogunate, all died in 1616.", links:["p:shakespeare","p:cervantes","p:tokugawa-ieyasu"]},
  {h:"Galileo and Shakespeare were born the same year", t:"Both were born in 1564. Galileo died in 1642, and Newton was born just under a year later.", links:["p:galileo","p:shakespeare","p:newton"]},
  {h:"Bach and Handel never met", t:"Born a month apart in 1685, in German towns under 200 km apart. When Handel visited his hometown of Halle in 1719, Bach traveled there to meet him and arrived too late.", links:["p:bach","p:handel"]},
  {h:"Harriet Tubman lived to see airplanes", t:"Tubman escaped slavery around 1849 and died in 1913, ten years after the Wright brothers' first flight.", links:["p:tubman","e:first-flight"]},
  {h:"Jefferson and Adams died on the same day", t:"Both died on July 4, 1826, exactly 50 years after the Declaration of Independence.", links:["p:jefferson","p:john-adams","e:us-independence"]},
  {h:"Joyce and Woolf were literary twins", t:"Both were born in 1882 and both died in 1941.", links:["p:joyce","p:woolf"]},
  {h:"Alan Turing was born the year the Titanic sank", t:"The Titanic went down in April 1912. Turing was born that June.", links:["p:turing","e:titanic"]},
  {h:"Hokusai outlived Beethoven by 22 years", t:"Hokusai was born ten years before Beethoven, and made The Great Wave a few years after Beethoven died.", links:["p:hokusai","p:beethoven"]},
  {h:"Penang and Figaro share a year", t:"George Town, Penang was founded in 1786, the same year Mozart's opera The Marriage of Figaro premiered in Vienna.", links:["e:penang-founded","p:mozart"]},
  {h:"Napoleon and Beethoven were born a year apart", t:"Napoleon in 1769, Beethoven in 1770. Beethoven first dedicated his Third Symphony to him.", links:["p:napoleon","p:beethoven"]},
  {h:"Mark Twain came and went with a comet", t:"Halley's Comet appeared in 1835, the year Twain was born, and returned in 1910, the year he died.", links:["p:mark-twain","p:halley"]},
  {h:"Zheng He sailed before Columbus", t:"Zheng He's fleets crossed the Indian Ocean from 1405, almost 90 years before Columbus set out in 1492.", links:["p:zheng-he","e:columbus-1492"]},
  {h:"The last emperor saw the space age", t:"Puyi became emperor of China in 1908 and lived until 1967, after Yuri Gagarin flew into space.", links:["p:puyi","e:first-human-space"]}
]
